import {COMPANY_POINTS} from './company-design.js';
import {MAIL_PATH} from './mail-run.js';
// Gameplay has one full-table pose. Only equipment work starts a finite close-up.
export const SLOPE=.035;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const controlSide=(side,view='reverse')=>view==='reverse'?(side==='left'?'right':'left'):side;
export function overviewPose(w,h,view='reverse'){const distance=w<h?112:82,sign=view==='reverse'?1:-1;return {position:[0,-.2+distance*.7,15+sign*distance],target:[0,-.2,15],fov:w<h?66:62};}
const world=(x,y,z)=>[x===0?0:-x,y*Math.cos(SLOPE)-z*Math.sin(SLOPE),y*Math.sin(SLOPE)+z*Math.cos(SLOPE)];
function fitDistance(points,target,w,h,pitch,sign,fov,mx=.91,my=.85){
 const length=Math.hypot(1,pitch),tan=Math.tan(fov*Math.PI/360),aspect=Math.max(.1,w/Math.max(1,h));let distance=1;
 for(const point of points){const p=world(...point),px=p[0]-target[0],py=p[1]-target[1],pz=p[2]-target[2],depth=Math.max(Math.abs(px)/(tan*aspect*mx),Math.abs(py-sign*pitch*pz)/(length*tan*my));distance=Math.max(distance,(depth+(pitch*py+sign*pz)/length)/length);}
 return distance;
}
// Bound real ground court, office and route/actor heights independently; no tall
// imaginary exterior-front corners that unnecessarily shrink the whole table.
const fullBounds=[...COMPANY_POINTS];
for(const [xs,zs,ys]of[[[-24.5,24.5],[-36,-15],[0]],[[-19,19],[-20,50.3],[0,7.5]],[[-18.8,18.8],[52.3],[2.2,6.05]]])
 for(const x of xs)for(const z of zs)for(const y of ys)fullBounds.push([x,y,z]);
for(const p of MAIL_PATH)for(const dx of [-1.8,1.8])for(const y of [0,5])fullBounds.push([p.x+dx,y,p.z]);
// Keep both outer lanes visible in portrait; larger distinct machines replace duplicates.
const criticalBounds=[];
for(const x of[-17.6,17.6])for(const z of[-20,49])for(const y of[0,4.8])criticalBounds.push([x,y,z]);
for(const p of MAIL_PATH)for(const dx of[-.85,.85])for(const y of[.3,4.8])criticalBounds.push([p.x+dx,y,p.z]);
function fullTableFit(w,h,pitch,sign,fov,top=0,bottom=0,portrait=false){
 const length=Math.hypot(1,pitch),tan=Math.tan(fov*Math.PI/360),highY=tan*(.97-2*top/h),lowY=tan*(-.97+2*bottom/h),kx=tan*w/Math.max(1,h)*(portrait?1.02:.94);
 const points=fullBounds.map(p=>{const[x,y,z]=world(...p);return{x,a:(pitch*y+sign*z)/length,b:(y-sign*pitch*z)/length};});
 // Camera depth must satisfy horizontal bounds and a nonempty vertical interval.
 const lower=Math.max(...points.map(p=>p.b+highY*p.a)),upper=Math.min(...points.map(p=>p.b+lowY*p.a));
 const depth=Math.max((lower-upper)/(highY-lowY),...points.map(p=>p.a+Math.abs(p.x)/kx),...criticalBounds.map(p=>{const[x,y,z]=world(...p);return (pitch*y+sign*z)/length+Math.abs(x)/(tan*w/h*.98);}));
 // Anchor the lowest real geometry above the home indicator. Controls overlay
 // this region; their height must not shrink or lift the board.
 const vertical=upper-lowY*depth;
 const center=(Math.max(...points.map(p=>p.a))+Math.min(...points.map(p=>p.a)))/2;
 return{x:0,y:(vertical+center*pitch)/length,z:sign*(-pitch*vertical+center)/length,distance:(depth-center)/length,close:0};
}
const ease=t=>t*t*t*(t*(t*6-15)+10);
export class StableRig{
 constructor(view='reverse'){this.view=view;this.reset();}
 reset(){this.key=null;this.mode='full';this.motion=null;this.x=0;this.z=9.5;this.y=0;this.distance=null;this.gate=false;this.close=0;}
 update(dt,w,h,ball,interaction=null,station=null,comfort=false,fitFrame=false){
  const portrait=fitFrame?.portrait??(w<h),pitch=portrait?1.35:clamp(1.35/(w/h),.45,.85),fov=portrait?32:38,sign=this.view==='reverse'?1:-1,top=portrait&&fitFrame?.safeTop!==undefined?100+(fitFrame?.safeTop||0):0,bottom=4+(fitFrame?.safeBottom||0),key=`${w}:${h}:${portrait}:${pitch}:${comfort}:${top}:${bottom}`;
  if(!interaction&&!fitFrame?.mail){if(ball.z+Math.max(0,ball.vz||0)*.4>=20)this.gate=true;else if(ball.z<12)this.gate=false;}
  if(this.key!==key){
   this.key=key;this.full=fullTableFit(w,h,pitch,sign,fov,top,bottom,portrait);
   Object.assign(this,this.full);this.mode='full';this.motion=null;
  }
  // The resolved-result launch animation gives half a second to reopen the table
  // before physics releases the person. Mail/gate/ball never change this target.
  const close=!!interaction&&!!station&&interaction.stage!=='launch',mode=close?`station:${station.id}`:'full';
  if(mode!==this.mode){
   let to=this.full;
   if(close){const dock=interaction.dock,target=world((dock.x+station.x)/2,2.2,(dock.z+station.z)/2),points=[],r=station.r+2.6;
    for(const x of[station.x-r,station.x+r])for(const z of[station.z-r,station.z+r])for(const y of[0,7])points.push([x,y,z]);
    for(const p of[dock,interaction.from].filter(Boolean))for(const x of[p.x-1.5,p.x+1.5])for(const z of[p.z-1.5,p.z+1.5])for(const y of[0,5])points.push([x,y,z]);
    to={x:target[0],y:target[1],z:target[2],distance:Math.max(12,fitDistance(points,target,w,h,pitch,sign,fov,.85,.83),this.full.distance*(comfort?.58:.22)),close:1};
   }
   this.motion={from:{x:this.x,y:this.y,z:this.z,distance:this.distance,close:this.close},to,elapsed:0,duration:close?(comfort?1.4:1.2):.5};this.mode=mode;
  }
  if(this.motion){const m=this.motion;m.elapsed=Math.min(m.duration,m.elapsed+Math.max(0,dt));const t=ease(m.elapsed/m.duration);for(const k of['x','y','z','distance','close'])this[k]=m.from[k]+(m.to[k]-m.from[k])*t;if(m.elapsed>=m.duration){Object.assign(this,m.to);this.motion=null;}}
  return {position:[this.x,this.y+this.distance*pitch,this.z+sign*this.distance],target:[this.x,this.y,this.z],fov};
 }
}

import {LAYOUT} from './route-layout.js';
import {REWARD_ITEMS} from './route-rewards.js';
import {MAIL_PATH,MAIL_LENGTH,MAIL_LENGTHS,mailPoint} from './mail-run.js';
export function buildMailOffice({T,office,label,C,view}){
 const root=new T.Group();root.name='mailLoop';office.add(root);const vectors=MAIL_PATH.map(p=>new T.Vector3(-p.x,.06,p.z)),left=[],right=[],positions=[],indices=[];
 for(let n=0;n<vectors.length;n++){const a=vectors[Math.max(0,n-1)],b=vectors[Math.min(vectors.length-1,n+1)],normal=new T.Vector3(b.z-a.z,0,a.x-b.x).normalize().multiplyScalar(1.55+1.45*Math.max(0,1-Math.min(MAIL_LENGTHS[n],MAIL_LENGTH-MAIL_LENGTHS[n])/8));left.push(vectors[n].clone().add(normal));right.push(vectors[n].clone().sub(normal));positions.push(...left[n].toArray(),...right[n].toArray());if(n){const i=n*2;indices.push(i-2,i-1,i,i-1,i+1,i);}}
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.setIndex(indices);geometry.computeVertexNormals();const lane=new T.Mesh(geometry,new T.MeshBasicMaterial({color:0x576e6d,side:T.DoubleSide}));lane.name='mailLane';root.add(lane);
 for(const x of [-7,7]){const pad=new T.Mesh(new T.PlaneGeometry(6,5),new T.MeshBasicMaterial({color:0x576e6d,side:T.DoubleSide}));pad.rotation.x=-Math.PI/2;pad.position.set(x,.065,34);pad.name='mailApron';root.add(pad);}
 for(const side of [left,right]){const rail=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(side),384,.11,5,false),new T.MeshBasicMaterial({color:0xe8ce77}));rail.position.y=.14;root.add(rail);}
 const arrows=[];for(let d=3;d<MAIL_LENGTH;d+=10){const p=mailPoint(d),g=new T.Group();g.position.set(-p.x,.13,p.z);g.rotation.y=Math.atan2(-p.dx,p.dz);const shape=new T.Shape();shape.moveTo(-.45,-.4);shape.lineTo(0,.45);shape.lineTo(.45,-.4);shape.lineTo(0,-.05);shape.closePath();const m=new T.Mesh(new T.ShapeGeometry(shape),new T.MeshBasicMaterial({color:0xffe29b,side:T.DoubleSide}));m.rotation.x=Math.PI/2;g.add(m);root.add(g);m.userData.heading=g.rotation.y;arrows.push(m);}
 const sign=(text,x,z,color)=>{const g=label(text,5.8,2.1,'#183a3c',color);g.name='mail-'+text;g.position.set(-x,.14,z);g.rotation.x=-Math.PI/2;g.rotation.z=view==='original'?Math.PI:0;g.userData.occludes=false;root.add(g);return g;};
 const upstreamArrow=view==='original'?'↓':'↑';const signs=[sign('氣送 '+upstreamArrow,-7,39,'#a5ddd5'),sign('快遞 '+upstreamArrow,7,39,'#ffce83')];
 // Painted entrance dots frame a target without covering the person or flipper landing zone.
 for(const x of [-10,-4,4,10]){const pole=new T.Mesh(new T.CylinderGeometry(.22,.22,.035,8),new T.MeshToonMaterial({color:C.yellow}));pole.position.set(-x,.08,34);root.add(pole);}
 const cart=new T.Group();cart.name='mailTrolley';root.add(cart);const base=new T.Mesh(new T.BoxGeometry(1.5,.25,2),new T.MeshToonMaterial({color:C.yellow}));base.position.y=.15;cart.add(base);for(const x of [-.7,.7])for(const z of [-.65,.65]){const wheel=new T.Mesh(new T.SphereGeometry(.18,8,6),new T.MeshToonMaterial({color:C.ink}));wheel.position.set(x,.12,z);cart.add(wheel);}const file=label('急件',1.2,.55);file.position.set(0,.3,.6);file.rotation.x=-Math.PI/2;file.userData.occludes=false;cart.add(file);cart.visible=false;
 const wake=new T.Group();wake.name='expressWake';cart.add(wake);for(const x of[-.65,.65])for(let n=0;n<3;n++){const m=new T.Mesh(new T.PlaneGeometry(.13,.8),new T.MeshBasicMaterial({color:0xfff1c8,side:T.DoubleSide,transparent:true,opacity:.65,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(x,.18,-1.5-n*.9);wake.add(m);}
 const boosters=[];for(const side of[-1,1])for(const z of[-8,1,10,19]){const g=new T.Group();g.name='expressMarker';g.position.set(side*22,.09,z);for(const x of[-.65,.65]){const m=new T.Mesh(new T.PlaneGeometry(.16,1.1),new T.MeshBasicMaterial({color:side>0?0xffcf7a:0x9ce6d8,side:T.DoubleSide}));m.rotation.set(-Math.PI/2,0,x>0?-.7:.7);m.position.x=x;g.add(m);}root.add(g);boosters.push(g);}
 const goals=[];for(const[x,z]of[[LAYOUT.copier.x,LAYOUT.copier.z],[LAYOUT.boss.x,LAYOUT.boss.z],[-7,34]]){const m=new T.Mesh(new T.RingGeometry(.9,1.15,24),new T.MeshBasicMaterial({color:0x758b89,side:T.DoubleSide}));m.rotation.x=-Math.PI/2;m.position.set(-x,.16,z);root.add(m);goals.push(m);}
 const stamp=label('全部退件！',8,2.2,'#9c332e','#ffe5bb');stamp.name='returnStamp';stamp.position.set(0,5.5,-18);stamp.rotation.y=view==='original'?Math.PI:0;stamp.userData.occludes=false;root.add(stamp);
 const papers=[];for(let n=0;n<12;n++){const m=new T.Mesh(new T.BoxGeometry(.65,.025,.9),new T.MeshBasicMaterial({color:n%2?0xffeac3:0xd8ebe4}));root.add(m);papers.push(m);}
 const rewards=REWARD_ITEMS.map((item,n)=>{const p=mailPoint(item.fraction*MAIL_LENGTH),g=new T.Group();g.name='routeItem-'+n;g.position.set(-p.x,.85,p.z);root.add(g);const envelope=new T.Mesh(new T.BoxGeometry(1.4,.25,1.1),new T.MeshToonMaterial({color:[0xa0e6d5,0xf3d16d,0xf0b4c5][n]}));g.add(envelope);const text=label(item.label+' +'+item.points,3,1);text.rotation.x=-Math.PI/2;text.rotation.z=view==='original'?Math.PI:0;text.position.y=.2;text.userData.occludes=false;g.add(text);return g;});
 const pulses=[];for(let n=0;n<16;n++){const m=new T.Mesh(new T.RingGeometry(.7,.9,16),new T.MeshBasicMaterial({color:0xb2fff0,transparent:true,opacity:.65,side:T.DoubleSide,depthWrite:false}));m.rotation.x=-Math.PI/2;m.name='routePulse';root.add(m);pulses.push(m);}
 return {root,cart,stamp,goals,rewards,update(game,time){
 rewards.forEach((g,n)=>{g.visible=game.routeRewards.active&&!game.routeRewards.collected[n];g.position.y=.85+Math.sin(game.effectTime*3+n)*.2;g.scale.setScalar(1+Math.sin(game.effectTime*4+n)*.08);});
 pulses.forEach((m,n)=>{m.visible=!!game.mailRun||game.routeRewards.active;if(m.visible){const direction=game.mailRun?.direction||1,d=(n/16*MAIL_LENGTH+game.effectTime*(game.mailRun?26:8))%MAIL_LENGTH,p=mailPoint(d);m.position.set(-p.x*direction,.2,p.z);m.scale.setScalar(game.mailRun?1.35:1);m.material.opacity=game.mailRun?.7:.35;}});
cart.visible=!!game.mailRun;if(cart.visible){cart.position.set(-game.ball.x,0,game.ball.z);cart.rotation.y=Math.atan2(-game.ball.vx,game.ball.vz);}wake.visible=!!game.mailRun&&game.mailRun.speed>42;if(wake.visible)wake.scale.z=.8+(game.mailRun.speed-42)/18;for(const g of boosters){const active=game.mailRun&&Math.abs(-game.ball.x-g.position.x)<3&&Math.abs(game.ball.z-g.position.z)<7;g.children.forEach(m=>m.material.color.setHex(active?0xfff4cc:g.position.x>0?0xffcf7a:0x9ce6d8));g.rotation.y=game.mailRun&&game.ball.vz>0?Math.PI:0;}const w=game.workflow;stamp.visible=w.active;stamp.rotation.z=w.active?Math.sin(game.effectTime*7)*.025:0;goals.forEach((m,n)=>m.material.color.setHex(w.lights[n]?0xffdb60:0x758b89));for(let n=0;n<papers.length;n++){const m=papers[n];m.visible=w.active;if(w.active){const p=mailPoint((n/12*MAIL_LENGTH+game.effectTime*15)%MAIL_LENGTH);m.position.set(-p.x,.5+Math.sin(n+game.effectTime*3)*.15,p.z);m.rotation.y=game.effectTime*2+n;}}arrows.forEach((m,n)=>{m.material.color.setHex(game.mailRun&&Math.abs(n*10+3-(game.mailRun.direction===-1?MAIL_LENGTH-game.mailRun.distance:game.mailRun.distance))<12?0xffffff:0xffdf8b);m.parent.rotation.y=m.userData.heading+(game.mailRun?.direction===-1?Math.PI:0);});signs.forEach(s=>s.material.color.setHex(game.mailLatch?.blocked?0x7d9693:0xffffff));}};
}

import {sweepRect} from './contact.js';
// One shared sampled centreline for physics and the visible, ground-level mail chute.
export const MAIL={entryX:-7,entryZ:34,halfMouth:2.2,minSpeed:16,minUpstream:12,minTravelSpeed:32,maxTravelSpeed:40,mouthDepth:1.2,clearance:.7,rearmDistance:2,points:350,exit:{x:7,z:34,vx:-12,vz:-34}};
const controls=[[-7,34],[-12,35],[-19,34],[-22,29],[-22,-16],[-18,-24],[0,-26],[18,-24],[22,-16],[22,29],[19,34],[12,35],[7,34]];
const point=t=>{const f=t*(controls.length-1),n=Math.min(controls.length-2,Math.floor(f)),u=f-n,p0=controls[Math.max(0,n-1)],p1=controls[n],p2=controls[n+1],p3=controls[Math.min(controls.length-1,n+2)];return{x:cat(p0[0],p1[0],p2[0],p3[0],u),z:cat(p0[1],p1[1],p2[1],p3[1],u)};};
function cat(a,b,c,d,t){return .5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);}
export const MAIL_PATH=Array.from({length:385},(_,n)=>point(n/384));
export const MAIL_LENGTHS=[0];for(let n=1;n<MAIL_PATH.length;n++)MAIL_LENGTHS.push(MAIL_LENGTHS[n-1]+Math.hypot(MAIL_PATH[n].x-MAIL_PATH[n-1].x,MAIL_PATH[n].z-MAIL_PATH[n-1].z));
export const MAIL_LENGTH=MAIL_LENGTHS.at(-1);
// Acceleration starts on the straight; the rear curve always slows for readability.
export function mailPhase(distance,direction=1,entrySpeed=32){const p=distance/MAIL_LENGTH;
 if(p<.1)return{id:'intake',label:direction===1?'氣送收件':'快遞收件',speed:entrySpeed};
 if(p<.28)return{id:'outbound',label:direction===1?'氣送加速':'轉寄快線',speed:direction===1?54:44};
 if(p<.66)return{id:'bend',label:'上方轉運',speed:30};
 return{id:'return',label:direction===1?'急件噴出':'退件連發',speed:direction===1?52:p<.8?44:58};
}
export function mailPoint(distance){const d=Math.max(0,Math.min(MAIL_LENGTH,distance));let lo=1,hi=MAIL_PATH.length-1;while(lo<hi){const m=(lo+hi)>>1;if(MAIL_LENGTHS[m]<d)lo=m+1;else hi=m;}const a=MAIL_PATH[lo-1],b=MAIL_PATH[lo],length=MAIL_LENGTHS[lo]-MAIL_LENGTHS[lo-1],t=(d-MAIL_LENGTHS[lo-1])/length;return{x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t,dx:(b.x-a.x)/length,dz:(b.z-a.z)/length};}
export function mailEntry(from,to){if(from.z<MAIL.entryZ||to.z>=MAIL.entryZ||to.vz>-MAIL.minUpstream||Math.hypot(to.vx,to.vz)<MAIL.minSpeed)return null;const t=(MAIL.entryZ-from.z)/(to.z-from.z),x=from.x+(to.x-from.x)*t;for(const direction of [1,-1])if(Math.abs(x-MAIL.entryX*direction)<=MAIL.halfMouth)return{x,z:MAIL.entryZ,direction};return null;}
export const WORKFLOW={goals:['print','sign','mail'],points:1800,duration:6,cooldown:8,hitPoints:300,hits:3};
export const freshWorkflow=()=>({lights:[false,false,false],active:false,until:0,readyAt:0,hitsLeft:0,rounds:0});

export const freshMailLatch=()=>({blocked:false,direction:1,travel:0});
export function lockMailExit(latch,direction){Object.assign(latch,{blocked:true,direction,travel:0});}
const mouthShape=direction=>({x:MAIL.exit.x*direction,z:MAIL.entryZ,hx:MAIL.halfMouth,hz:MAIL.mouthDepth});
export function mailMouthContains(p,direction,radius=.65){return !!sweepRect(p,p,mouthShape(direction),radius+MAIL.clearance);}
export function advanceMailLatch(latch,from,to,radius=.65){
 if(!latch.blocked||!from||!to)return;
 const distance=Math.hypot(to.x-from.x,to.z-from.z);if(!Number.isFinite(distance))return;
 // Animation and teleport never call this. Only fully clear physical flight earns credit.
 if(sweepRect(from,to,mouthShape(latch.direction),radius+MAIL.clearance))latch.travel=0;else latch.travel+=distance;
 if(latch.travel>=MAIL.rearmDistance){latch.blocked=false;latch.travel=0;}
}

